SELECT concat(toString(cohort), ' · ', toString(count()), if(count() = 1, ' user', ' users')) AS "Cohort (week of)",
       if(cohort + INTERVAL 1 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 1 WEEK)) / count(), 4), NULL) AS "W1",
       if(cohort + INTERVAL 2 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 2 WEEK)) / count(), 4), NULL) AS "W2",
       if(cohort + INTERVAL 3 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 3 WEEK)) / count(), 4), NULL) AS "W3",
       if(cohort + INTERVAL 4 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 4 WEEK)) / count(), 4), NULL) AS "W4",
       if(cohort + INTERVAL 5 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 5 WEEK)) / count(), 4), NULL) AS "W5",
       if(cohort + INTERVAL 6 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 6 WEEK)) / count(), 4), NULL) AS "W6",
       if(cohort + INTERVAL 7 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 7 WEEK)) / count(), 4), NULL) AS "W7",
       if(cohort + INTERVAL 8 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 8 WEEK)) / count(), 4), NULL) AS "W8",
       if(cohort + INTERVAL 9 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 9 WEEK)) / count(), 4), NULL) AS "W9",
       if(cohort + INTERVAL 10 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 10 WEEK)) / count(), 4), NULL) AS "W10",
       if(cohort + INTERVAL 11 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 11 WEEK)) / count(), 4), NULL) AS "W11"
FROM (
    SELECT UserId, min(week) AS cohort, groupUniqArray(week) AS weeks
    FROM (
        SELECT UserId, toMonday(Timestamp) AS week
        FROM product_events
        WHERE UserId != '' AND Timestamp >= {to:DateTime64(9)} - INTERVAL 90 DAY AND Timestamp < {to:DateTime64(9)} AND (empty({env_ids:Array(String)}) OR has({env_ids:Array(String)}, EnvId)) AND (empty({services:Array(String)}) OR has({services:Array(String)}, ServiceName))
    )
    GROUP BY UserId
)
WHERE cohort >= toMonday({to:DateTime64(9)}) - INTERVAL 11 WEEK
GROUP BY cohort ORDER BY cohort

SELECT cohort,
       if(cohort + INTERVAL 1 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 1 WEEK)) / count(), 4), NULL) AS "Week 1",
       if(cohort + INTERVAL 2 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 2 WEEK)) / count(), 4), NULL) AS "Week 2",
       if(cohort + INTERVAL 4 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 4 WEEK)) / count(), 4), NULL) AS "Week 4",
       if(cohort + INTERVAL 8 WEEK <= toMonday({to:DateTime64(9)}), round(1 * countIf(has(weeks, cohort + INTERVAL 8 WEEK)) / count(), 4), NULL) AS "Week 8"
FROM (
    SELECT UserId, min(week) AS cohort, groupUniqArray(week) AS weeks
    FROM (
        SELECT UserId, toMonday(Timestamp) AS week
        FROM product_events
        WHERE UserId != '' AND Timestamp >= {to:DateTime64(9)} - INTERVAL 90 DAY AND Timestamp < {to:DateTime64(9)} AND (empty({env_ids:Array(String)}) OR has({env_ids:Array(String)}, EnvId)) AND (empty({services:Array(String)}) OR has({services:Array(String)}, ServiceName))
    )
    GROUP BY UserId
)
WHERE cohort >= toMonday({to:DateTime64(9)}) - INTERVAL 11 WEEK
GROUP BY cohort ORDER BY cohort
